mapper.select:
SELECT w.withdrawal_id,w.enrollment_id,w.reason,w.requested_at,w.status,w.reviewed_by,w.reviewed_at,
       w.review_note,w.approved_refund_amount,w.refund_amount,w.refund_method,w.refund_voucher,w.refunded_by,w.refunded_at
FROM withdrawal_request w JOIN enrollment e ON e.enrollment_id = w.enrollment_id

    e.student_user_id = #{studentUserId}
    AND w.status = #{status}

ORDER BY w.requested_at DESC, w.withdrawal_id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM withdrawal_request w JOIN enrollment e ON e.enrollment_id = w.enrollment_id

    e.student_user_id = #{studentUserId}
    AND w.status = #{status}
